import{z as B,x as m,o as E,c as A,q as i,j as o,D as r,d as t,s as l,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const R=JSON.parse('{"title":"CIR 一般均衡利率","description":"","frontmatter":{"title":"CIR 一般均衡利率","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/cir-general-equilibrium.md","filePath":"econ/cir-general-equilibrium.md","lastUpdated":1791413859000}'),d={name:"econ/cir-general-equilibrium.md"};function p(c,a,C,h,u,D){const s=m("Mermaid");return E(),A("div",null,[a[2]||(a[2]=i('<h1 id="cir-一般均衡利率" tabindex="-1">CIR 一般均衡利率 <a class="header-anchor" href="#cir-一般均衡利率" aria-label="Permalink to &quot;CIR 一般均衡利率&quot;">​</a></h1><div class="epigraph"><p>短期利率是均衡里资本的边际与消费的边际对齐之后的过程；平方根扩散保证正利率，波动随水平升。</p><footer>—— Cox, Ingersoll and Ross, An Intertemporal General Equilibrium Model of Asset Prices, Econometrica, 1985；A Theory of the Term Structure of Interest Rates, Econometrica, 1985</footer></div><p><a href="/econ/continuous-time-capm">上一课</a>把 \\(r\\) 当参数，给资产标瞬时 beta。本课缺口是<strong>利率从哪来</strong>：生产技术加状态变量，出清的瞬时无风险利率成为 \\(z\\) 的函数，债券价格由同一 \\(m\\) 给出期限结构。不重写 EH 的宏观课，不估计仿射模型的卡尔曼滤波。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Cox、Ingersoll 与 Ross（1985）：连续时间生产，状态 \\(z\\)（例如技术冲击）驱动边际产出，代表性主体优化。瞬时 \\(r\\) 等于财富的影子收益率（或消费欧拉的漂移项），债券是对一单位计价物在 \\(T\\) 的要求权，价格 \\(P(t,T;z)\\) 满足偏微——生成元来自 \\(m\\) 或来自风险中性下 \\(z\\) 的漂移。平方根过程 \\(\\mathrm{d}r=\\kappa(\\bar r-r)\\mathrm{d}t+\\sigma\\sqrt{r}\\,\\mathrm{d}B\\) 是他们选出的闭式特化：零是可及或不可及取决于参数，利率不为负，波动与水平同向。缺口是：期限结构可以是一般均衡的产出，而不必是外生因子的仿射。</p><p>主干仿射课把因子当给定。本课指出 CIR 的因子有生产解释。两课不互相替换：仿射是计算族，CIR 是均衡选取。</p><p><span class="marginnote">术语翻译：\\(\\mathrm{d}r=\\kappa(\\bar r-r)\\mathrm{d}t+\\sigma\\sqrt{r}\\,\\mathrm{d}B\\) 读作——利率像一根拴在 \\(\\bar r\\) 上的皮筋，离得越远被拉回的力 \\(\\kappa(\\bar r-r)\\) 越大（均值回复）；随机抖动的幅度不是常数 \\(\\sigma\\)，而是 \\(\\sigma\\sqrt{r}\\)，即利率越高抖得越厉害。这就是「平方根扩散」的全部含义。</span></p><p><span class="marginnote">两篇 1985 <em>Econometrica</em>：一篇一般均衡资产价格，一篇期限结构闭式。Vasicek 是高斯外生利率，可为负；CIR 用 \\(\\sqrt{r}\\) 挡零。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>均衡：\\(m=\\mathrm{e}^{-\\rho t}u&#39;(c_t)\\)，\\(c\\) 由生产与状态决定。\\(r\\) 由 \\(1=\\mathrm{E}[m(1+r\\mathrm{d}t+\\ldots)]\\) 的瞬时给出。债券 \\(P=\\mathrm{E}[m_T/m_t]\\)。选技术使 \\(r\\) 本身是仿射（或平方根）状态，PDE 有指数仿射解。风险价格由生产风险与 \\(u\\) 决定，不是外生 \\(\\lambda\\)。</p>',10)),(E(),o(n,null,{default:r(()=>[l(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20TECH%5B%22%E7%94%9F%E4%BA%A7%20%2B%20%E7%8A%B6%E6%80%81%20z%22%5D%20--%3E%20R%5B%22%E5%9D%87%E8%A1%A1%E7%9E%AC%E6%97%B6%20r(z)%22%5D%0A%20%20R%20--%3E%20BOND%5B%22%E5%80%BA%E5%88%B8%20P(t%2CT%3Bz)%22%5D%0A%20%20M%5B%22m%20%3D%20MRS%22%5D%20--%3E%20BOND%0A%20%20BOND%20--%3E%20TS%5B%22%E5%9D%87%E8%A1%A1%E6%9C%9F%E9%99%90%E7%BB%93%E6%9E%84%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与 Lucas 树：树无生产，\\(r\\) 由果实的条件矩给出，也可以有期限结构，但没有资本。CIR 让资本存在，\\(r\\) 与投资机会锁在一起——对冲需求的 \\(z\\) 正是这个状态。连续时间 CAPM 在此成为「瞬时股票相对瞬时 \\(r\\)」的切片；整条债券曲线由同一均衡生成。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"机制是跨期生产的一阶。资本的边际产出高时，主体要求更高的 \\(r\\) 才愿意把消费挪到今天（或相反，取决于如何标状态）。均值回复来自技术或偏好把 \\(z\\) 拉回。波动随 \\(r\\) 升：高利率状态下技术更抖——这是闭式需要的假设，不是数据。债券风险来自 \\(r\\) 的扩散：长久期暴露 \\(r\\) 的对冲价格，接风险的期限结构课，但对象是确定支付，不是股利条。",-1)),(E(),o(n,null,{default:r(()=>[l(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20DR%5B%22%E5%88%A9%E7%8E%87%E8%BF%87%E7%A8%8B%EF%BC%9A%E6%BC%82%E7%A7%BB%20%CE%BA(%20r%CC%84%20%E2%88%92%20r%20)dt%20%E5%8A%A0%E6%B3%A2%E5%8A%A8%E9%A1%B9%22%5D%20--%3E%20V%5B%22Vasicek%EF%BC%9A%E6%B3%A2%E5%8A%A8%E9%A1%B9%20%3D%20%CF%83%20dB%22%5D%0A%20%20DR%20--%3E%20C%5B%22CIR%EF%BC%9A%E6%B3%A2%E5%8A%A8%E9%A1%B9%20%3D%20%CF%83%E2%88%9Ar%20dB%22%5D%0A%20%20V%20--%3E%20NEG%5B%22%E6%AD%A3%E6%80%81%E6%89%B0%E5%8A%A8%E4%B8%8D%E8%AE%BE%E5%A2%99%EF%BC%9A%E5%88%A9%E7%8E%87%E5%8F%AF%E4%B8%BA%E8%B4%9F%22%5D%0A%20%20C%20--%3E%20POS%5B%22r%20%E8%B6%8A%E9%AB%98%E6%8A%96%E5%8A%A8%E8%B6%8A%E5%A4%A7%EF%BC%8C%E4%BD%86%200%20%E6%98%AF%E5%9C%B0%E6%9D%BF%22%5D%0A%20%20POS%20--%3E%20AFF%5B%22%E5%80%BA%E5%88%B8%E4%BB%B7%E6%A0%BC%E4%BB%8D%E6%98%AF%E6%8C%87%E6%95%B0%E4%BB%BF%E5%B0%84%E9%97%AD%E5%BC%8F%22%5D%0A%20%20NEG%20--%3E%20NUM%5B%22%E6%95%B0%E5%80%BC%E4%B8%8A%E8%A6%81%E5%8F%A6%E5%A4%84%E7%90%86%E8%B4%9F%E5%80%BC%E4%B8%8E%E5%AE%9A%E4%BB%B7%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p><span class="marginnote">直觉类比：把 \\(r\\) 想成水温。Vasicek 允许水温随机晃过冰点以下（负利率）；CIR 假设水越热晃动越猛，但温度不会跌破「绝对零度」——平方根 \\(\\sqrt{r}\\) 在 \\(r=0\\) 处把抖动收缩到零，恰好把利率挡在地板上。很多「利率不会为负」的模型直觉，就是从这一项来的。</span></p><p><span class="marginnote">便利收益会让国债不再是纯 CIR 债券。本课纯计价物要求权。安全资产课的服务流在 CIR 里相当于改支付，不是改 PDE 装置。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把平方根估计成短期利率的唯一真相。高斯、多因子、跳跃是别的特化。下一课把同一均衡装置对准期权：Black–Scholes 公式可以是复制，也可以是某个均衡里 \\(m\\) 恰好使波动定价与复制一致。CIR 给利率；BS 给股票期权——完全市场里两者都是 \\(\\mathbb{Q}\\)–期望。</p><p><span class="marginnote">常见误区：以为 Vasicek 与 CIR 只是波动项的写法差别，小事一桩。实际上这一项决定利率能否为负、波动是否随水平变化，进而决定债券期权有没有下界、闭式解还能不能用。2010 年代后的负利率环境里，\\(\\sqrt{r}\\) 的地板假设本身也成了需要重新审视的模型选择。</span></p><p>后课默认：CIR 把 \\(r\\) 从参数升级为均衡扩散；债券价格由同一 \\(m\\) 的 PDE 给出。仿射是计算，生产是解释。不是 EH 的宏观检验。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一般均衡对齐生产与消费的边际，给出瞬时 \\(r(z)\\)。</li><li>平方根特化：正利率、水平依赖波动、债券闭式。</li><li>期限结构与股票瞬时 CAPM 共用 \\(m\\)，支付不同。</li><li>出处：Cox, Ingersoll and Ross, <em>Econometrica</em> 1985（两篇）。</li></ul>',8))])}const _=B(d,[["render",p]]);export{R as __pageData,_ as default};
